import { HttpService } from '@nestjs/axios';
import { AxiosRequestConfig, AxiosResponse, isAxiosError } from 'axios';
import { acquireServiceCredential } from '../discovery/service-credential';

// Exported so the generated resilience-config spec can assert the value this
// generator baked in equals the value the resilience profile declared. An
// assertion over an unexported literal could only restate the literal.
export const DEFAULT_TIMEOUT_MS = 10000;

/**
 * A resilient request failed: names the target, the method and the status. Never the URL
 * or the request headers, which an axios error's `config` holds. `status` is undefined
 * when the target gave no response.
 */
export class ResilientCallError extends Error {
  readonly target: string;
  readonly method: string;
  readonly status: number | undefined;

  constructor(target: string, method: string, status: number | undefined) {
    const outcome = status === undefined ? 'no response' : `status ${status}`;
    super(`Call to '${target}' ${method} failed: ${outcome}.`);
    this.name = 'ResilientCallError';
    this.target = target;
    this.method = method;
    this.status = status;
  }
}

/** The typed error of a failed request: reads only the status, never the error's text. */
function resilientCallError(target: string, method: string, error: unknown): ResilientCallError {
  return new ResilientCallError(target, method, isAxiosError(error) ? error.response?.status : undefined);
}

@Injectable()
export class ResilientClientService {
  private readonly logger = new Logger(ResilientClientService.name);

  constructor(private readonly httpService: HttpService) {}

  private async getAuthHeaders(): Promise<Record<string, string>> {
    const credential = await acquireServiceCredential();
    return { Authorization: `Bearer ${credential}` };
  }

  /**
   * Make an HTTP request with timeout using AbortController.
   *
   * The log lines and the timeout error name the logical `target` (the dependency
   * the request goes to), never the resolved URL: the peer's address stays out of
   * the logs.
   */
  async request(
    target: string,
    method: string,
    url: string,
    config: AxiosRequestConfig = {},
    timeoutMs: number = DEFAULT_TIMEOUT_MS,
  ): Promise<AxiosResponse> {
    // The credential is acquired before the request's own timeout starts: its
    // acquisition is bounded on its own and is never charged to the request.
    const authHeaders = await this.getAuthHeaders();
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

    this.logger.debug(`HTTP request started: target=${target} method=${method} timeout=${timeoutMs}ms`);

    try {
      const response = await this.httpService.axiosRef.request({
        method,
        url,
        ...config,
        headers: { ...config.headers, ...authHeaders },
        signal: controller.signal,
      });
      this.logger.debug(
        `HTTP request completed: target=${target} method=${method} status=${response.status}`,
      );
      return response;
    } catch (error: unknown) {
      const err = error as { name?: string };
      if (err.name === 'CanceledError' || err.name === 'AbortError') {
        this.logger.warn(`HTTP request timed out: target=${target} method=${method} timeout=${timeoutMs}ms`);
        throw new Error(`Request to ${target} timed out after ${timeoutMs}ms`);
      }
      throw resilientCallError(target, method, error);
    } finally {
      clearTimeout(timeoutId);
    }
  }
}
